//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

// 시장지 결과조회 
scwin.vScrenID = "ULDINS20600.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 시장지 결과  조회한다. TBLD_B_SECURPT_FILE
 ***********************************************/
scwin.ins_search = function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS20600_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listEtcMktTrsInquiry" + "&{P}EDATE=" + edt_EDATE.getValue() + "&{P}SDATE=" + edt_SDATE.getValue();
    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};

/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 시장지 결과 상세 조회한다. 
 ***********************************************/
scwin.ins_detail = function(TRD_DD, SECURPT_TP_CD) {
    trs_modify.Action = "/EtcInfoAction.do?method=readEtcMktTrsInquiry" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SECURPT_TP_CD=" + SECURPT_TP_CD + "&TRD_DD=" + TRD_DD;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst)";
    //trs_modify.Parameters	= "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email ;  
    trs_modify.Post();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.stf.fn_setFromToDate(1, edt_SDATE, edt_EDATE);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert('dts_List.OnLoadCompleted('+rowcount+')');
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    txa_SECURPT_BINFILE.text = "";
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (row == 0) return;
    var SECURPT_TP_CD = dts_List.getCellData(row, "SECURPT_TP_CD");
    var TRD_DD = dts_List.getCellData(row, "TRD_DD");
    scwin.ins_detail(TRD_DD, SECURPT_TP_CD);
};
scwin.dts_Rst_OnLoadCompleted = function(rowcount) {
    //alert('dts_Rst.OnLoadCompleted('+rowcount+')');

};
scwin.trs_modify_OnFail = function() {
    alert_tr_error(trs_modify);
    //alert('trs_modify.OnFail()');

};
scwin.trs_modify_OnSuccess = function() {
    //alert('trs_modify.OnSuccess()');

};
